#include "tools_view.h"
#include "view_zoom.h"
#include <cstdio>
#include <fstream>
#include <stdexcept>
#include <vector>
using V=ux::ToolsView;
#define CHECK(v) do{if(!(v))throw std::runtime_error(#v);}while(0)
static V::Snapshot snapshot(){return {{"11111111-1111-4111-8111-111111111111",std::string(64,'a'),1},{V::Tool::Ballpoint,V::Width::Medium,0,false},false,false,true,true};}
static V::Command tap(V& v,spike::Rect r,const V::Snapshot& s){return v.hit((r.x0+r.x1)/2,(r.y0+r.y1)/2,s);}
int main(int argc,char**argv){unsigned cases=0;auto test=[&](const char* name,auto f){f();++cases;std::printf("PASS %s\n",name);};try{
 test("viewport_focal_inverse_pan_damage_and_reset",[]{ux::ViewZoom v;CHECK(!v.active());CHECK(v.zoom(2,400,600));auto source=v.inverse(400,600);CHECK(std::abs(source.first-400)<1e-9&&std::abs(source.second-600)<1e-9);auto p=v.map(500,650);auto back=v.inverse(p.first,p.second);CHECK(std::abs(back.first-500)<1e-9&&std::abs(back.second-650)<1e-9);CHECK(v.pan(-100000,100000));auto r=v.source({0,0,1620,2060});CHECK(r.x0>=0&&r.y0>=0&&r.x1<=1620&&r.y1<=2060);CHECK(!v.zoom(0,800,900));CHECK(!v.zoom(INFINITY,800,900));CHECK(!v.zoom(2,-1,0));v.reset();CHECK(v.scale()==1&&v.map(300,200)==std::pair(300.,200.));});
 test("snap_is_highlighter_context_bound_and_contact_safe",[]{auto s=snapshot();V pen;CHECK(pen.open(s));CHECK(tap(pen,ib::reader::snapCell(),s).action==V::Action::None);s.style.tool=V::Tool::Highlighter;s.style.color=4;V highlighter;CHECK(highlighter.open(s));auto c=tap(highlighter,ib::reader::snapCell(),s);CHECK(c.action==V::Action::Snap&&!c.snapHighlights&&highlighter.snapshot().snapHighlights);CHECK(tap(highlighter,ib::reader::snapCell(),s).refusal==V::Refusal::Busy);s.snapHighlights=false;++s.binding.revision;CHECK(highlighter.update(s));CHECK(tap(highlighter,ib::reader::snapCell(),s).snapHighlights);s.contact=true;V contact;CHECK(contact.open(s));CHECK(tap(contact,ib::reader::snapCell(),s).refusal==V::Refusal::Busy);s.contact=false;s.busy=true;V busy;CHECK(busy.open(s));CHECK(tap(busy,ib::reader::snapCell(),s).refusal==V::Refusal::Busy);});
 test("nine_tool_indices_and_legal_highlighter_default",[]{for(unsigned n=0;n<9;++n){V v;auto s=snapshot();CHECK(v.open(s));auto c=tap(v,V::toolRect(n),s);CHECK(c.action==V::Action::Tool&&unsigned(c.style.tool)==n&&!c.style.eraser&&c.binding==s.binding);CHECK(c.style.color==(n==8?4u:0u));}});
 test("three_width_and_eight_palette_indices",[]{for(unsigned n=0;n<3;++n){V v;auto s=snapshot();CHECK(v.open(s));auto c=tap(v,V::widthRect(n),s);CHECK(c.action==V::Action::Width&&unsigned(c.style.width)==n);}for(unsigned n=0;n<8;++n){V v;auto s=snapshot();CHECK(v.open(s));auto c=tap(v,V::colorRect(n),s);CHECK(c.action==V::Action::Color&&c.style.color==n);CHECK(V::colorRgb(n)&0xff000000u);}});
 test("eraser_toggle_and_undo_redo_availability",[]{auto s=snapshot();V v;CHECK(v.open(s));CHECK(tap(v,V::eraser(),s).style.eraser);s.style.eraser=true;++s.binding.revision;CHECK(v.update(s));CHECK(!tap(v,V::eraser(),s).style.eraser);V u;CHECK(u.open(s));CHECK(tap(u,V::undo(),s).action==V::Action::Undo);V r;CHECK(r.open(s));CHECK(tap(r,V::redo(),s).action==V::Action::Redo);s.canUndo=s.canRedo=false;V denied;CHECK(denied.open(s));CHECK(tap(denied,V::undo(),s).refusal==V::Refusal::Unavailable);CHECK(tap(denied,V::redo(),s).refusal==V::Refusal::Unavailable);});
 test("contact_blocks_all_actions_busy_allows_close",[]{auto s=snapshot();V contact;CHECK(contact.open(s));s.contact=true;CHECK(tap(contact,V::toolRect(1),s).refusal==V::Refusal::Busy);CHECK(tap(contact,contact.closeRect(),s).action==V::Action::None&&contact.active());s.contact=false;s.busy=true;V busy;CHECK(busy.open(s));CHECK(tap(busy,V::undo(),s).refusal==V::Refusal::Busy);V style;CHECK(style.open(s));CHECK(tap(style,V::toolRect(1),s).action==V::Action::Tool);V width;CHECK(width.open(s));CHECK(tap(width,V::widthRect(2),s).action==V::Action::Width);CHECK(tap(busy,busy.closeRect(),s).action==V::Action::Close&&!busy.active());});
 test("stale_document_page_revision_and_style_taps_refused",[]{for(unsigned n=0;n<4;++n){auto s=snapshot();V v;CHECK(v.open(s));if(n==0)s.binding.document="different";if(n==1)s.binding.page="different";if(n==2)++s.binding.revision;if(n==3)s.style.color=1;auto c=tap(v,V::toolRect(1),s);CHECK(c.action==V::Action::None&&c.refusal==V::Refusal::Stale&&c.consumed);CHECK(tap(v,v.closeRect(),s).action==V::Action::None);}});
 test("pending_command_requires_new_revision_no_optimistic_style",[]{auto s=snapshot();V v;CHECK(v.open(s));auto c=tap(v,V::toolRect(2),s);CHECK(v.pending()&&v.snapshot().style==s.style);CHECK(tap(v,V::undo(),s).refusal==V::Refusal::Busy);CHECK(v.update(s)&&v.pending());s.style=c.style;++s.binding.revision;CHECK(v.update(s)&&!v.pending()&&v.snapshot().style==c.style);});
 test("binding_update_invalidates_old_panel_and_older_revision_refused",[]{auto s=snapshot();s.binding.revision=8;V v;CHECK(v.open(s));v.takeDamage();auto older=s;older.binding.revision=7;CHECK(!v.update(older)&&v.snapshot().binding==s.binding);auto next=s;next.binding.page=std::string(64,'b');next.binding.revision=1;CHECK(v.update(next));CHECK(v.takeDamage().x1==V::panel().x1);CHECK(tap(v,V::toolRect(1),s).refusal==V::Refusal::Stale);CHECK(tap(v,V::toolRect(1),next).action==V::Action::Tool);});
 test("highlighter_black_refused_without_hiding_other_colors",[]{auto s=snapshot();s.style.tool=V::Tool::Highlighter;s.style.color=4;V v;CHECK(v.open(s));CHECK(tap(v,V::colorRect(0),s).refusal==V::Refusal::Unavailable&&!v.pending());CHECK(tap(v,V::colorRect(7),s).style.color==7);});
 test("modal_outside_touch_consumed_without_clickthrough",[]{auto s=snapshot();V v;CHECK(!v.hit(0,0,s).consumed);CHECK(v.open(s));for(auto p:std::array<std::array<int,2>,5>{{{0,0},{1619,2159},{50,1000},{1400,1900},{800,2100}}}){auto c=v.hit(p[0],p[1],s);CHECK(c.consumed&&c.action==V::Action::None);}CHECK(v.active()&&!v.pending());});
 test("invalid_snapshot_never_opens_or_replaces_valid_state",[]{auto s=snapshot();V v;auto bad=s;bad.style.color=8;CHECK(!v.open(bad));CHECK(v.open(s));bad=s;bad.binding.revision=0;CHECK(!v.update(bad)&&v.snapshot().binding==s.binding);bad=s;bad.style.tool=V::Tool::Highlighter;CHECK(!V::valid(bad));});
 test("paint_fixed_rgb32_bounds_damage_padding_and_small_surface_refusal",[&]{auto s=snapshot();V v;CHECK(v.open(s));auto damage=v.takeDamage();CHECK(damage.x0==V::panel().x0&&damage.y1==V::panel().y1);CHECK(v.takeDamage().empty());constexpr unsigned stride=1632;std::vector<std::uint32_t> pixels(stride*2160+16,0xffabcdef);CHECK(v.paint({pixels,1620,2160,stride}));bool changed=false;for(unsigned y=0;y<2160;++y)for(unsigned x=0;x<stride;++x){bool in=x>=unsigned(V::panel().x0)&&x<unsigned(V::panel().x1)&&y>=unsigned(V::panel().y0)&&y<unsigned(V::panel().y1);if(!in)CHECK(pixels[y*stride+x]==0xffabcdef);else changed|=pixels[y*stride+x]!=0xffabcdef;}CHECK(changed);for(unsigned i=stride*2160;i<pixels.size();++i)CHECK(pixels[i]==0xffabcdef);auto copy=pixels;CHECK(!v.paint({std::span(pixels.data(),100),1620,2160,stride})&&pixels==copy);if(argc==2){std::ofstream out(argv[1],std::ios::binary);out<<"P6\n1620 2160\n255\n";for(unsigned y=0;y<2160;++y)for(unsigned x=0;x<1620;++x){auto c=pixels[y*stride+x];out.put(char(c>>16));out.put(char(c>>8));out.put(char(c));}}CHECK(tap(v,v.closeRect(),s).action==V::Action::Close);CHECK(v.takeDamage().y0==V::panel().y0);});
 std::printf("TOOLS_VIEW_TESTS_PASS cases=%u touch_commands_only=1 vendor=NONE input_devices=NONE\n",cases);return 0;
 }catch(const std::exception& e){std::fprintf(stderr,"TOOLS_VIEW_TEST_FAIL %s\n",e.what());return 1;}}
